{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: казначейское сопровождение строительных контрактов", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Казначейское сопровождение", "description": "Контроль целевого расходования бюджетных средств: подрядчику открывают лицевой счёт, а платежи проходят санкционирование (гл. 24.4 Бюджетного кодекса)."}, {"@type": "DefinedTerm", "name": "Лицевой счёт (код 71)", "description": "Счёт неучастника бюджетного процесса в казначействе, на котором учитываются целевые средства по сопровождаемому контракту."}, {"@type": "DefinedTerm", "name": "КС-2", "description": "Акт о приёмке выполненных работ (форма по Постановлению Госкомстата № 100), подтверждающий объём и виды выполненных строительных работ."}, {"@type": "DefinedTerm", "name": "КС-3", "description": "Справка о стоимости выполненных работ и затрат (форма по Постановлению Госкомстата № 100), по которой определяется сумма к оплате."}, {"@type": "DefinedTerm", "name": "Санкционирование", "description": "Проверка казначейством расходной операции на соответствие целям, документам и условиям контракта перед перечислением средств."}, {"@type": "DefinedTerm", "name": "Упрощённый порядок расчётов", "description": "Порядок 2026 года (ст. 15 ФЗ № 431-ФЗ), при котором по ряду строительных контрактов оплата идёт на расчётный счёт подрядчика в банке, а не через лицевой счёт."}, {"@type": "DefinedTerm", "name": "Идентификатор государственного контракта (ИГК)", "description": "Код, связывающий всех участников цепочки исполнения контракта — от заказчика до поставщиков материалов."}]}
